UPDATE herb_image
SET process_status = #{processStatus},
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND is_deleted = 0

UPDATE herb_image
SET is_deleted = 1,
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND is_deleted = 0

